import {
  type Popover as PopoverController,
  type PopoverPlacement,
  createPopover,
} from "@cssints/headless";
import { Portal } from "@solidjs/web";
import type { JSX } from "@solidjs/web";
import * as css from "cssints" with { type: "cssints" };
import { createContext, merge, omit, onCleanup, useContext } from "solid-js";

import { Button } from "./button.tsx";
import { type PartProps, renderPart, type Renderable } from "./render.tsx";
import { t } from "./theme.ts" with { type: "cssints" };

export interface PopoverProps {
  /** The accessible name of the content: the primitive announces a `role="dialog"` and a dialog needs one. */
  readonly label: string;
  /** Where the panel opens; the primitive flips it to the other side when the viewport has no room. */
  readonly placement?: PopoverPlacement;
  /** The gap to the trigger, in px. */
  readonly offset?: number;
  /** Controlled: the host owns the open state and this is the only thing that opens or closes it. */
  readonly open?: boolean;
  /** Open at mount; ignored while `open` is set. */
  readonly defaultOpen?: boolean;
  /** A request to change the open state: uncontrolled it is accepted, controlled the host may ignore it. */
  readonly onOpenChange?: (open: boolean) => void;
  readonly id?: string;
  readonly children?: JSX.Element;
}

export type PopoverTriggerPartProps = PartProps;

export interface PopoverTriggerProps extends Renderable<PopoverTriggerPartProps, void> {
  readonly class?: string;
  readonly children?: JSX.Element;
}

export type PopoverContentPartProps = PartProps;

export interface PopoverContentProps extends Renderable<PopoverContentPartProps, void> {
  readonly class?: string;
  readonly children?: JSX.Element;
}

const PopoverContext = createContext<{
  readonly popover: PopoverController;
  readonly label: () => string;
  /** The two refs the primitive's `attach` needs: it wires them once both exist. */
  readonly connect: (part: "trigger" | "content", element: HTMLElement) => void;
}>();

// The panel is portalled to `document.body`, unlike the menu's, the select's and the tooltip's: the primitive writes
// page-space `top` / `left` (`attach` measures against the viewport and adds the scroll) for a `position: absolute` panel,
// and that is only true in the initial containing block. A `position: relative` anchor around the trigger would make the
// panel absolute in that box and put it at the page's top-left. The portal also keeps the panel out of an ancestor's
// `overflow: hidden` or `transform`, which is the other half of the same problem. The cost: the panel is a client-only
// island (no server paint) and it is not where the trigger is in the DOM, so the primitive measures the trigger once per
// open and again on resize, scroll and a `ResizeObserver`.
//
// No `display` here on purpose: the primitive hides the panel with the `hidden` attribute, and a display declaration in this
// class would override the UA's `[hidden] { display: none }`. The position comes from the primitive's `contentStyle()`.
const contentClass = css.cn(
  css.zIndex("var(--z-popover)"),
  css.minWidth("max-content"),
  css.maxWidth("min(24rem, calc(100vw - 2rem))"),
  css.padding(t.space._3),
  css.bg(t.color.overlayBackground),
  css.color(t.color.text),
  css.border("1px solid", t.color.overlayBorder),
  css.borderRadius(t.radius.lg),
  css.boxShadow(t.shadow.popover),
  // the content takes focus with `tabindex="-1"` when it holds nothing focusable: a ring around the whole panel is noise
  css.outline("none"),
);

/**
 * A non-modal popover, styled: `Popover.Trigger` opens `Popover.Content`, a floating panel with `role="dialog"` and no
 * `aria-modal`. `createPopover` owns the open state (controlled by `open`), the trigger's `aria-haspopup` / `aria-expanded` /
 * `aria-controls`, Enter, Space and ArrowDown to open, Escape to close, the placement and its flip at the viewport edge, the
 * outside `pointerdown` that light-dismisses, and the focus into the panel and back to the trigger. The kit adds the surface,
 * the accessible name, and the portal the primitive's page-space placement needs.
 *
 * Not modal, deliberately: the page behind keeps its focus, its clicks and its scroll, and Tab leaves the panel. The content is
 * the caller's — a form, a few controls — and nothing here is a menu: `Menu` owns a menu's roving focus and can sit inside
 * this panel.
 */
export const Popover = (props: PopoverProps): JSX.Element => {
  const popover = createPopover({
    id: props.id,
    get placement() {
      return props.placement;
    },
    get offset() {
      return props.offset;
    },
    get open() {
      return props.open;
    },
    defaultOpen: props.defaultOpen,
    get onOpenChange() {
      return props.onOpenChange;
    },
  });
  // The primitive wires two elements and creates an effect, so it is attached from the parts' refs: `ref` travels with the
  // props, so a `render` that spreads them keeps the wiring. Its teardown runs with the root.
  let trigger: HTMLElement | undefined;
  let content: HTMLElement | undefined;
  let detach: (() => void) | undefined;
  const connect = (part: "trigger" | "content", element: HTMLElement): void => {
    if (part === "trigger") {
      trigger = element;
    } else {
      content = element;
    }
    if (trigger !== undefined && content !== undefined && detach === undefined) {
      detach = popover.attach(trigger, content);
    }
  };
  onCleanup(() => {
    detach?.();
    detach = undefined;
  });
  return (
    <PopoverContext value={{ popover, label: () => props.label, connect }}>
      {props.children}
    </PopoverContext>
  );
};

/** The button that opens the panel: `Button` unless `render` says otherwise. It is the element with `aria-haspopup`. */
export const PopoverTrigger = (props: PopoverTriggerProps): JSX.Element => {
  const { popover, connect } = useContext(PopoverContext);
  const rest = omit(props, "render", "class", "children");
  // no `data-part` of its own: the part renders a `Button`, which owns the attribute, as `Dialog.Trigger` does
  const merged = merge(rest, popover.triggerProps, () => ({
    get class() {
      return css.cn(props.class);
    },
    ref: (element: HTMLElement) => {
      connect("trigger", element);
    },
  }));
  return renderPart(props, merged, undefined, (part) => (
    <Button {...part}>{props.children}</Button>
  ));
};

/**
 * The panel, portalled to the body and placed by the primitive. It stays in the DOM and `hidden` while the popover is closed,
 * because `aria-controls` names it (and the primitive needs the element to measure and to move focus into on open).
 */
export const PopoverContent = (props: PopoverContentProps): JSX.Element => {
  const { popover, label, connect } = useContext(PopoverContext);
  const merged = merge(omit(props, "render", "class", "children"), popover.contentProps, () => ({
    "aria-label": label(),
    "data-part": "popover",
    get class() {
      return css.cn(contentClass, props.class);
    },
    ref: (element: HTMLElement) => {
      connect("content", element);
    },
  }));
  return (
    <Portal>
      {renderPart(props, merged, undefined, (part) => (
        <div {...part} style={popover.contentStyle()}>
          {props.children}
        </div>
      ))}
    </Portal>
  );
};

import type { JSX } from "@solidjs/web";
import { untrack } from "solid-js";

/**
 * What a part hands to `render`: the props the part owns (`id`, `aria-*`, `data-part`, `class`) and the state it is in, as
 * accessors — Solid does not re-render a component, so a snapshot would be dead on the second read.
 *
 * Base UI's `render` takes an element and clones it with the part's props; Solid cannot clone (JSX is already a node), so
 * the element form becomes the function form and a component is that function: `render={(props) => <a {...props} />}`,
 * `render={Button}`.
 */
export type Render<P extends object, S> = (props: P, state: S) => JSX.Element;

/**
 * What a part hands to `render`: element-generic attributes, because the element is the caller's (`<a>`, `<textarea>`, a
 * component). `ref` stays the caller's too — a part cannot type a ref for an element it has not chosen.
 */
export type PartProps = Omit<JSX.HTMLAttributes<HTMLElement>, "ref"> & {
  readonly class?: string;
};

/** A part that anything can render: `render` replaces its element and keeps the props the part owns. */
export interface Renderable<P extends object, S> {
  readonly render?: Render<P, S> | undefined;
}

/**
 * Renders a part: the caller's `render` when it gave one, the part's own element otherwise. `render` is structural, so it is
 * read once (untracked): a part that swapped it at run time would need a remount, not an update.
 *
 * @param {Renderable<P, S>} part the component's props, for the `render` it may carry
 * @param {P} props the part's props, already merged with the caller's own and with `class` and `data-part`
 * @param {S} state the part's state, as accessors
 * @param {(props: P) => JSX.Element} fallback the element the part is by default
 * @returns {JSX.Element} the part
 */
export const renderPart = <P extends object, S>(
  part: Renderable<PartProps, S>,
  props: P,
  state: S,
  fallback: (props: P) => JSX.Element,
): JSX.Element => {
  const render = untrack(() => part.render);
  // the part hands more than `PartProps` (its own element's attributes: `type` on a button, `value` on an input); a render
  // function is typed by what every part guarantees, and reads the rest as the DOM attributes they are
  return render === undefined ? fallback(props) : render(props as PartProps, state);
};

import { look } from "@cssints/mise-en-mode" with { type: "cssints" };
import { check, createGlobalTheme, createTokens, media } from "cssints" with { type: "cssints" };

import { darkTheme, forcedColorsTheme, lightTokens } from "./tokens.ts";

// The theme the starters are written against: one lightness scale, one hue and one chroma per
// colour family, and the semantic colours made of them. The data lives in tokens.ts, so the
// registry can compile it to a plain theme.css without the cssints plugin; this module is the
// same theme for the components and the demo page, with the contrast gate.
const t = createTokens(lightTokens);

// The dark mode is the lightness scale turned over, so every step and every colour made of it follows: the text is still
// gray-1200, it is just a light gray now. The page and the surface are the reference's own dark values, and the popover shadow
// deepens because a shadow on a dark page reads as a smudge.
createGlobalTheme(t, media("(prefers-color-scheme: dark)"), darkTheme);

// The same dark look as a scope a page can ask for: `<div data-mode="dark">` moves every token inside it, and a surface or a
// frame under it follows without a prop. It is a mise-en-mode look, so it is in the `app` layer: a host's `author` or `viewer`
// look over the same marker wins without a specificity trick, and `data-mode="dark/color"` moves the colours alone. The media
// query above stays a global theme: a look is a `data-mode` scope, and the system preference is not one.
look(t, "dark", "app", darkTheme);

// One preset, because the theme is neutral: the reference's indigo, as its two numbers. The others are in its theme.css.
createGlobalTheme(t, '[data-tint="indigo"]', {
  hue: { tint: "284.23" },
  chroma: { tint: "0.25049" },
});

// On a dense screen (200dpi and up) the targets grow: the spacing steps and the text with them, as in the reference.
createGlobalTheme(t, media("(min-resolution: 200dpi)"), {
  space: { base: "calc(0.25rem * 1.25)" },
  font: { sizeSm: "0.9375rem", size: "1.0625rem", sizeLg: "1.25rem" },
});

// Windows high contrast mode throws the theme away and paints the system's own colours; forced-colors makes that explicit,
// since a component that reads a token here gets the system colour rather than the tint.
createGlobalTheme(t, media("(forced-colors: active)"), forcedColorsTheme);

// The pairs a reader meets on every page: body text, the second level of text, and a link on a card. Both modes and every
// theme above are checked (the preset too, since it sets the tokens the link is made of), and a ratio under the floor fails
// the build. 7 for text and 4.5 for the rest are the WCAG 2.x AAA and AA floors.
check.contrast(t.color.text, t.color.page, { min: 7 }); // the tabs skin's selected label
check.contrast(t.color.muted, t.color.page, { min: 4.5 }); // its unselected label
check.contrast(t.color.link, t.color.surface, { min: 4.5 });
check.contrast(t.color.placeholder, t.color.page, { min: 4.5 });
check.contrast(t.color.onHighlight, t.color.highlight, { min: 4.5 });
// The active tab's underline is a graphic against the page: 3 is the WCAG 1.4.11 floor for non-text contrast. The dark
// mode is the closest (3.55:1 without the preset, 3.17:1 with indigo), so a lighter highlight would break it.
check.contrast(t.color.highlight, t.color.page, { min: 3 });
// The focus ring is a graphic, not text: 3 is the WCAG 1.4.11 floor for a non-text contrast.
check.contrast(t.color.focusRing, t.color.page, { min: 3 }); // the tabs skin's ring

export { t };

import { render } from "@solidjs/web";

import { Popover, PopoverContent, PopoverTrigger } from "./popover.tsx";

/**
 * Mounts the styled popover in ordinary use, inside an ancestor that would clip an inline layer (`overflow: hidden`) and
 * whose `transform` would become the containing block of an absolute one: the panel is portalled out of both.
 */
export const mountPopover = (): { readonly root: HTMLElement; readonly dispose: () => void } => {
  const root = document.createElement("div");
  root.style.overflow = "hidden";
  root.style.transform = "translateZ(0)";
  document.body.append(root);

  const dispose = render(
    () => (
      <Popover label="Rename file" placement="bottom-start">
        <PopoverTrigger>Rename</PopoverTrigger>
        <PopoverContent>
          <input data-part="popover-field" value="Report Q3" aria-label="Name" />
          <button data-part="popover-save" type="button">
            Save
          </button>
        </PopoverContent>
      </Popover>
    ),
    root,
  );

  return {
    root,
    dispose: () => {
      dispose();
      root.remove();
    },
  };
};

/**
 * The DOM side of the popover's conformance test. There is no APG pattern for a popover and no Quint spec, so there is no
 * scenario walk: the primitive's own browser test is the oracle for the behaviour, and this driver is what the kit's test
 * reads — the parts by name, a real click and key, and a settle that lets Solid 2 deliver the event and apply the update.
 */
export interface PopoverMounted {
  readonly root: HTMLElement;
  readonly dispose: () => void;
}

/** Solid 2 delivers events through its delegated listener on a later turn. */
export const settle = (): Promise<void> => new Promise((resolve) => setTimeout(resolve, 20));

const required = <T extends HTMLElement>(parent: ParentNode, selector: string): T => {
  const element = parent.querySelector<T>(selector);
  if (element === null) {
    throw new Error(`popover: no ${selector}`);
  }
  return element;
};

export const popoverDriver = (mounted: PopoverMounted) => {
  // the panel lives in a portal, not under the trigger: it is found on the document
  const content = (): HTMLElement => required(document, '[data-part="popover"]');
  return {
    trigger: (): HTMLButtonElement => required(mounted.root, '[aria-haspopup="dialog"]'),
    content,
    inside: (name: string): HTMLElement => required(content(), `[data-part="${name}"]`),
    open: async (): Promise<void> => {
      required<HTMLButtonElement>(mounted.root, '[aria-haspopup="dialog"]').click();
      await settle();
    },
    click: async (element: HTMLElement): Promise<void> => {
      element.click();
      await settle();
    },
    /** A key on whatever holds the focus, as a reader's would arrive. */
    press: async (key: string, init: KeyboardEventInit = {}): Promise<KeyboardEvent> => {
      const target =
        document.activeElement instanceof HTMLElement ? document.activeElement : document.body;
      const event = new KeyboardEvent("keydown", { key, bubbles: true, cancelable: true, ...init });
      target.dispatchEvent(event);
      await settle();
      return event;
    },
    style: (element: Element): CSSStyleDeclaration => getComputedStyle(element),
  };
};

import { afterEach, describe, expect, it } from "vite-plus/test";

import { mountPopover } from "./popover.fixture";
import { popoverDriver, settle, type PopoverMounted } from "./popover-driver.ts";

const live: PopoverMounted[] = [];

const mounted = (): ReturnType<typeof popoverDriver> & PopoverMounted => {
  const instance = mountPopover();
  live.push(instance);
  return { ...popoverDriver(instance), ...instance };
};

afterEach(() => {
  for (const instance of live.splice(0)) {
    instance.dispose();
  }
});

describe("Popover (the kit's DOM)", () => {
  it("is a closed dialog wired to its trigger", () => {
    const { trigger, content } = mounted();
    expect(trigger().getAttribute("aria-haspopup")).toBe("dialog");
    expect(trigger().getAttribute("aria-expanded")).toBe("false");
    expect(trigger().getAttribute("aria-controls")).toBe(content().id);
    expect(content().getAttribute("role")).toBe("dialog");
    expect(content().getAttribute("aria-modal")).toBeNull();
    expect(content().getAttribute("aria-label")).toBe("Rename file");
    expect(content().getAttribute("tabindex")).toBe("-1");
    expect(content().hidden).toBe(true);
    // hidden has to mean hidden: no display in the panel's class may override the UA's `[hidden] { display: none }`
    expect(getComputedStyle(content()).display).toBe("none");
  });

  it("portals the panel out of a clipping, transformed ancestor", async () => {
    const { root, content, open } = mounted();
    await open();
    expect(root.contains(content())).toBe(false);
    expect(content().parentElement).toBe(document.body);
    expect(content().hidden).toBe(false);
    // the ancestor's transform is not the panel's containing block: it is placed in page space
    expect(content().style.position).toBe("absolute");
    expect(content().style.top.endsWith("px")).toBe(true);
  });

  it("places the panel under the trigger, one gap below its bottom edge", async () => {
    const { trigger, content, open } = mounted();
    await open();
    await settle();
    const anchor = trigger().getBoundingClientRect();
    const panel = content().getBoundingClientRect();
    // placement="bottom-start", the primitive's default 4 px offset, both written in page space
    expect(Math.round(panel.top - window.scrollY)).toBe(Math.round(anchor.bottom + 4));
    expect(Math.round(panel.left - window.scrollX)).toBe(Math.round(anchor.left));
  });

  it("paints the surface from the theme and puts it under a dialog in the stack", async () => {
    const { content, open, style } = mounted();
    await open();
    const panel = style(content());
    // the surface is the theme's token, not a colour of the skin's own
    const probe = document.createElement("div");
    probe.style.backgroundColor = "var(--color-overlay-background)";
    document.body.append(probe);
    expect(panel.backgroundColor).toBe(style(probe).backgroundColor);
    probe.remove();
    expect(panel.borderTopWidth).toBe("1px");
    expect(panel.borderRadius).not.toBe("0px");
    expect(panel.boxShadow).not.toBe("none");
    expect(panel.zIndex).toBe("10");
  });

  it("moves the focus into the panel on open and back to the trigger on Escape", async () => {
    const { trigger, content, inside, open, press } = mounted();
    trigger().focus();
    await open();
    expect(document.activeElement).toBe(inside("popover-field"));
    await press("Escape");
    expect(content().hidden).toBe(true);
    expect(trigger().getAttribute("aria-expanded")).toBe("false");
    expect(document.activeElement).toBe(trigger());
  });

  it("closes on an outside press and leaves the focus where the page put it", async () => {
    const { trigger, content, open } = mounted();
    await open();
    const page = document.createElement("button");
    document.body.append(page);
    page.focus();
    page.dispatchEvent(new PointerEvent("pointerdown", { bubbles: true, cancelable: true }));
    await settle();
    expect(content().hidden).toBe(true);
    expect(trigger().getAttribute("aria-expanded")).toBe("false");
    expect(document.activeElement).toBe(page);
    page.remove();
  });
});

import solid from "@solidjs/vite-plugin";
import cssints, { targets } from "cssints/vite";
import { defineConfig } from "vite-plus";
import { playwright } from "vite-plus/test/browser-playwright";

// The conformance test a starter arrives with runs in a real Chromium: the scenario walk needs a
// real DOM and Solid 2's reactivity, not a simulated one.
export default defineConfig({
  // `evaluation.inline`: a browser-mode runner inlines everything as ESM, so the plugin's own
  // evaluation server keeps the framework's packages inlined (Solid resolves its client build by
  // them) and the rest external (Node loads their CJS). Without it, a click's target resolves
  // against a second copy of Solid and the walk reads a state the page never changed.
  plugins: [
    cssints({ evaluation: { inline: ["solid-js", "@solidjs/web", "@solidjs/signals"] } }),
    solid(),
  ],
  css: { transformer: "lightningcss", lightningcss: { targets } },
  // The plugin adds `import derived from "cssints/derived"` to a client module after the dep
  // scanner has run; pre-bundling it here is what keeps that from reloading the page mid-test.
  optimizeDeps: { include: ["cssints/derived"] },
  test: {
    // a browser test has no app entry: the sheet of the modules the test imports arrives through
    // `virtual:cssints.css`, and vitest drops CSS imports unless it is told to process them
    css: true,
    // the sheet is loaded by the test's imports, not before them
    setupFiles: ["src/sheet.ts"],
    include: ["src/components/ui/**/*.browser.test.tsx"],
    browser: {
      enabled: true,
      provider: playwright(),
      headless: true,
      viewport: { width: 1280, height: 1024 },
      instances: [{ browser: "chromium" }],
      // The default waits 60 s for a worker's iframe to come up, which a busy machine (or a CI runner with a dozen other
      // jobs) misses: the run then fails as `the iframe did not become ready` with no test having run. Nothing about a
      // test gets longer; this is the browser starting.
      connectTimeout: 120_000,
      // the iframe ready timeout is read from the config's own env, not from the process that started the run
      env: { VITEST_BROWSER_IFRAME_TIMEOUT: "120000" },
    },
  },
});

// The engine's sheet for a browser test: its content is the CSS of the modules transformed so far, so it is loaded once the
// test file's imports are in (in `beforeAll`, not as a static import: vitest resolves the graph as it goes, and a sheet loaded
// first is just the `@layer` statement). A component's conformance test clicks its parts, so the sheet has to be there.
import { beforeAll } from "vite-plus/test";

beforeAll(async () => {
  await import("virtual:cssints.css");
});
